// 1. Validate incoming lead payload
const body = $input.item.json.body || $input.item.json;
const companyId = body.companyId;
const companyName = body.companyName || 'Unknown Company';
const website = (body.website || '').trim();
const industry = body.industry || '';
const location = body.location || 'UAE';

if (!companyId) {
  throw new Error('Validation failed: companyId is required.');
}

return {
  json: {
    companyId,
    companyName,
    website,
    industry,
    location,
    receivedAt: new Date().toISOString()
  }
};

// 2. Deep Digital Presence & Evidence Fingerprinting
const httpData = $input.item.json || {};
const lead = $('Validate Lead').first().json;

const hasUrl = Boolean(lead.website && lead.website.length > 2);
const isError = Boolean(httpData.error || httpData.statusCode === undefined || httpData.statusCode >= 400);
const isOk = hasUrl && !isError;
const html = typeof httpData.data === 'string' ? httpData.data : (typeof httpData === 'string' ? httpData : '');

const hasMobile = /<meta[^>]*name=["']viewport["'][^>]*content=["'][^"']*width=device-width/i.test(html);
const hasHttps = (lead.website || '').startsWith('https://');
const hasForm = /<form/i.test(html) && /(contact|message|submit|enquiry|email|name)/i.test(html);
const hasBooking = /(calendly\.com|booksy\.com|fresha\.com|book-now|schedule|appointment)/i.test(html);
const hasPortfolio = /(portfolio|projects|gallery|our-work|works|case-studies)/i.test(html);
const hasWhatsapp = /(wa\.me|api\.whatsapp\.com\/send)/i.test(html);

// Tech stack detection
const cms = [];
if (/wp-content|wordpress/i.test(html)) cms.push('WordPress');
if (/shopify/i.test(html)) cms.push('Shopify');
if (/webflow/i.test(html)) cms.push('Webflow');
if (/wix/i.test(html)) cms.push('Wix');
if (/squarespace/i.test(html)) cms.push('Squarespace');

const frameworks = [];
if (/_next/i.test(html)) frameworks.push('Next.js');
if (/react/i.test(html)) frameworks.push('React');
if (/vue/i.test(html)) frameworks.push('Vue');

const analytics = [];
if (/googletagmanager|google-analytics|gtag/i.test(html)) analytics.push('Google Analytics (GA4)');
if (/connect\.facebook\.net/i.test(html)) analytics.push('Meta Pixel');
if (/hotjar/i.test(html)) analytics.push('Hotjar');

const chatWidgets = [];
if (hasWhatsapp) chatWidgets.push('WhatsApp Direct Link');
if (/intercom/i.test(html)) chatWidgets.push('Intercom');
if (/crisp/i.test(html)) chatWidgets.push('Crisp');
if (/tidio/i.test(html)) chatWidgets.push('Tidio');
if (/tawk\.to/i.test(html)) chatWidgets.push('Tawk.to');

const detectedProblems = [];
const evidenceMatrix = [];
let websiteScore = 100;

if (!hasUrl) {
  websiteScore = 0;
  detectedProblems.push('No dedicated verified website URL');
  evidenceMatrix.push({
    observation: 'No registered web presence detected.',
    evidence: 'Lead record has no verified website endpoint.',
    impact: 'Losing high-intent UAE commercial search traffic to competitors.',
    recommendedSolution: 'Build a modern greenfield business website.',
    confidence: 95,
    truthTier: 'VERIFIED',
    category: 'PRESENCE'
  });
} else if (!isOk) {
  websiteScore = 15;
  detectedProblems.push('Website offline or unreachable');
  evidenceMatrix.push({
    observation: 'Website server is unreachable or returned error.',
    evidence: `HTTP request failed (${httpData.error || 'Offline'}).`,
    impact: 'Commercial clients encounter offline errors, damaging reputation.',
    recommendedSolution: 'Restore server uptime and deploy cloud hosting.',
    confidence: 90,
    truthTier: 'VERIFIED',
    category: 'UPTIME'
  });
} else {
  if (!hasHttps) {
    detectedProblems.push('Missing SSL encryption (Plain HTTP in use)');
    websiteScore -= 20;
    evidenceMatrix.push({
      observation: 'Website lacks SSL encryption.',
      evidence: 'Domain loads over insecure HTTP.',
      impact: 'Triggers browser security warnings, destroying trust.',
      recommendedSolution: 'Configure SSL certificate and enforce HTTPS.',
      confidence: 100,
      truthTier: 'VERIFIED',
      category: 'SECURITY'
    });
  }
  if (!hasMobile) {
    detectedProblems.push('No responsive mobile viewport detected');
    websiteScore -= 25;
    evidenceMatrix.push({
      observation: 'Mobile viewport meta tag is missing.',
      evidence: 'HTML lacks responsive viewport tag.',
      impact: 'High bounce rate for UAE mobile visitors.',
      recommendedSolution: 'Rebuild with mobile-first responsive architecture.',
      confidence: 100,
      truthTier: 'VERIFIED',
      category: 'MOBILE'
    });
  }
  if (!hasForm && !hasBooking) {
    detectedProblems.push('No direct enquiry or booking mechanism on primary landing');
    websiteScore -= 20;
    evidenceMatrix.push({
      observation: 'No direct enquiry form or booking flow detected.',
      evidence: 'No <form> or scheduling widget found.',
      impact: 'Interested buyers encounter friction trying to reach sales.',
      recommendedSolution: 'Implement high-converting lead capture funnels.',
      confidence: 95,
      truthTier: 'VERIFIED',
      category: 'CONVERSION'
    });
  }
  if (!hasPortfolio) {
    detectedProblems.push('Project portfolio is difficult to discover');
    websiteScore -= 15;
    evidenceMatrix.push({
      observation: 'Completed projects portfolio is difficult to discover.',
      evidence: 'No dedicated portfolio/project navigation link found.',
      impact: 'High-ticket buyers cannot verify previous craftsmanship.',
      recommendedSolution: 'Deploy a high-resolution project portfolio showcase.',
      confidence: 88,
      truthTier: 'INFERRED',
      category: 'PORTFOLIO'
    });
  }
  if (hasWhatsapp && chatWidgets.length === 1) {
    evidenceMatrix.push({
      observation: 'Business promotes WhatsApp but lacks automated 24/7 qualification.',
      evidence: 'Direct WhatsApp link detected without automated bot layer.',
      impact: 'Delayed responses during off-hours risk losing hot prospects.',
      recommendedSolution: 'Deploy 24/7 AI WhatsApp Qualification Bot.',
      confidence: 90,
      truthTier: 'INFERRED',
      category: 'AI_AUTOMATION'
    });
  }
  websiteScore = Math.max(20, Math.min(100, websiteScore));
}

const techStack = [...cms, ...frameworks, ...analytics, ...chatWidgets];

return {
  json: {
    companyId: lead.companyId,
    companyName: lead.companyName,
    website: lead.website,
    industry: lead.industry,
    location: lead.location,
    websiteStatus: !hasUrl ? 'NO_WEBSITE' : (isOk ? 'ONLINE' : 'OFFLINE'),
    websiteScore,
    hasMobile,
    hasHttps,
    hasForm,
    hasBooking,
    hasPortfolio,
    hasWhatsapp,
    techStack,
    digitalPresence: {
      cms,
      frameworks,
      analytics,
      chatWidgets,
      hasWhatsapp,
      hasHttps,
      hasMobileViewport: hasMobile,
      hasContactForm: hasForm,
      hasBooking,
      hasPortfolio
    },
    detectedProblems,
    evidenceMatrix
  }
};

// 3. AI Opportunity Analysis, 15-Service Matching & Dual Scoring Engine (Commercial Claims Accuracy)
const d = $input.item.json;
const industry = (d.industry || '').toLowerCase();

let opportunityScore = 70;
let confidenceScore = 80;
let recommendedServiceCode = 'PREMIUM_WEBSITE_REDESIGN';
let recommendedServiceName = 'Premium Website Redesign & Conversion Architecture';
let primaryPainPoint = '';
let reasoning = '';
let potentialImpact = '';
let reasonToContact = '';
let suggestedOffer = '';
let expectedBusinessBenefit = '';
let claimType = 'ESTIMATE';
let pitchAngle = '';
let estimatedBudgetMin = 35000;
let estimatedBudgetMax = 75000;
let recommendedChannel = 'EMAIL';
const evidenceSummary = [];

if (d.websiteStatus === 'NO_WEBSITE' || d.websiteStatus === 'OFFLINE') {
  opportunityScore = 92;
  confidenceScore = 95;
  recommendedServiceCode = 'NEW_HIGH_CONVERTING_WEBSITE';
  recommendedServiceName = 'New High-Converting Business Website & Digital Presence';
  primaryPainPoint = 'No active verified web presence exists to capture direct client search and high-ticket enquiries.';
  reasoning = `The business is established in ${d.location || 'UAE'} but lacks an online headquarters to capture commercial search demand.`;
  potentialImpact = 'Establish direct search authority and create a verified digital acquisition channel.';
  reasonToContact = `Your business is active in ${d.location || 'UAE'}, but without a dedicated website you are losing inbound client search demand directly to competitors.`;
  suggestedOffer = `Custom Greenfield Digital Presence & Portfolio for ${d.companyName}`;
  expectedBusinessBenefit = 'Create a clearer inbound path for potential clients searching for your services and establish direct digital credibility.';
  claimType = 'INFERRED_INSIGHT';
  pitchAngle = 'Direct ownership of digital client acquisition channel without relying solely on social media';
  estimatedBudgetMin = 28000;
  estimatedBudgetMax = 60000;
  recommendedChannel = 'WHATSAPP';
  evidenceSummary.push('Zero verified website domain or web infrastructure detected.');
} else if (!d.hasMobile) {
  opportunityScore = 88;
  confidenceScore = 92;
  recommendedServiceCode = 'PREMIUM_WEBSITE_REDESIGN';
  recommendedServiceName = 'Mobile-First Website Redesign & Modernization';
  primaryPainPoint = 'Website layout lacks a responsive mobile viewport, creating immediate conversion friction for smartphone visitors.';
  reasoning = 'A significant majority of commercial UAE traffic originates from mobile devices; non-responsive viewports increase visitor drop-off.';
  potentialImpact = 'Reduce mobile visitor bounce and eliminate interface scaling friction for smartphone visitors.';
  reasonToContact = 'Your website content is solid, but the layout is not optimized for mobile screens, creating friction for smartphone visitors.';
  suggestedOffer = `Modern Mobile-First Web Architecture for ${d.companyName}`;
  expectedBusinessBenefit = 'Improve mobile user experience and remove layout friction for smartphone visitors.';
  claimType = 'INFERRED_INSIGHT';
  pitchAngle = 'Mobile viewport friction audit showing immediate conversion drop-off';
  estimatedBudgetMin = 35000;
  estimatedBudgetMax = 70000;
  evidenceSummary.push('Missing responsive mobile viewport in HTML source.');
} else if (!d.hasHttps) {
  opportunityScore = 85;
  confidenceScore = 95;
  recommendedServiceCode = 'CYBERSECURITY_REVIEW_HARDENING';
  recommendedServiceName = 'Web Security Review & Vulnerability Hardening';
  primaryPainPoint = 'Domain is missing SSL encryption, triggering browser "Not Secure" warnings for prospective clients.';
  reasoning = 'Missing HTTPS flags security warnings in modern browsers, destroying client trust and search engine visibility.';
  potentialImpact = 'Eliminate browser security warnings and protect customer privacy across all enquiry forms.';
  reasonToContact = 'Your website is currently triggering "Not Secure" browser warnings because SSL encryption is inactive on your domain.';
  suggestedOffer = `Security & SSL Infrastructure Upgrade for ${d.companyName}`;
  expectedBusinessBenefit = 'Eliminate browser security warnings and protect customer enquiry transmission with standard SSL encryption.';
  claimType = 'VERIFIED_FACT';
  pitchAngle = 'Browser security trust badge and search penalty mitigation';
  estimatedBudgetMin = 18000;
  estimatedBudgetMax = 45000;
  evidenceSummary.push('Site loads over plain HTTP protocol without active SSL certificate.');
} else if (d.hasWhatsapp && (industry.includes('clinic') || industry.includes('consult') || industry.includes('salon') || industry.includes('interior') || industry.includes('fitout') || industry.includes('real estate'))) {
  opportunityScore = 90;
  confidenceScore = 90;
  recommendedServiceCode = 'AI_LEAD_QUALIFICATION_BOT';
  recommendedServiceName = 'AI Lead Qualification & 24/7 WhatsApp Conversational System';
  primaryPainPoint = 'Business promotes WhatsApp contact but relies on manual replies, creating severe delays during off-hours.';
  reasoning = 'Inbound prospects expect timely responses; automated conversational qualification captures lead details and intent promptly.';
  potentialImpact = 'Improve inquiry capture during off-hours and streamline initial client qualification.';
  reasonToContact = 'You provide a direct WhatsApp link on your site, but without an automated conversational bot, you risk losing prospects who message during off-hours.';
  suggestedOffer = `24/7 AI Receptionist & WhatsApp Booking Integration for ${d.companyName}`;
  expectedBusinessBenefit = 'Enable faster automated responses and lead qualification through WhatsApp.';
  claimType = 'INFERRED_INSIGHT';
  pitchAngle = 'Instant off-hours lead qualification and calendar booking';
  estimatedBudgetMin = 25000;
  estimatedBudgetMax = 55000;
  recommendedChannel = 'WHATSAPP';
  evidenceSummary.push('Direct WhatsApp link detected without conversational qualification layer.');
} else if (!d.hasPortfolio && (industry.includes('interior') || industry.includes('architecture') || industry.includes('fitout') || industry.includes('design'))) {
  opportunityScore = 89;
  confidenceScore = 88;
  recommendedServiceCode = 'PREMIUM_WEBSITE_REDESIGN';
  recommendedServiceName = 'Luxury Portfolio & Web Showcase Architecture';
  primaryPainPoint = 'Project portfolio and completed client case studies are difficult to discover on primary navigation.';
  reasoning = 'Commercial interior and design buyers make selection decisions primarily on visual proof of past project scale.';
  potentialImpact = 'Provide clear visual proof of past craftsmanship and elevate digital brand authority.';
  reasonToContact = 'Your craftsmanship and project reputation are strong, but your current web presence makes it difficult for potential commercial clients to quickly view your completed projects.';
  suggestedOffer = `Luxury Portfolio & Case Study Showcase for ${d.companyName}`;
  expectedBusinessBenefit = 'Provide immediate visual proof of project scale to prospective commercial clients and streamline proposal discussions.';
  claimType = 'INFERRED_INSIGHT';
  pitchAngle = 'Focus on portfolio discovery bottleneck rather than generic redesign';
  estimatedBudgetMin = 38000;
  estimatedBudgetMax = 80000;
  evidenceSummary.push('No dedicated portfolio or case study showcase on primary navigation.');
} else {
  opportunityScore = 72;
  confidenceScore = 80;
  recommendedServiceCode = 'PERFORMANCE_SEO_UPGRADE';
  recommendedServiceName = 'Technical SEO & Speed Optimization Engine';
  primaryPainPoint = 'Digital presence lacks modern Core Web Vitals optimization and structured search discovery signals.';
  reasoning = 'Speed optimization and clean schema markup improve organic search visibility and retain prospective buyers.';
  potentialImpact = 'Strengthen search engine discovery signals and optimize visitor loading speed.';
  reasonToContact = 'Your website is active, but missing schema markup and Core Web Vitals optimizations are holding back your organic search ranking in Dubai.';
  suggestedOffer = `Technical SEO & Performance Architecture for ${d.companyName}`;
  expectedBusinessBenefit = 'Improve page load responsiveness and strengthen technical search discovery foundations.';
  claimType = 'ESTIMATE';
  pitchAngle = 'Measurable speed and search indexing improvements';
  estimatedBudgetMin = 20000;
  estimatedBudgetMax = 45000;
  evidenceSummary.push('Core Web Vitals can be accelerated to improve technical search positioning.');
}

return {
  json: {
    companyId: d.companyId,
    websiteStatus: d.websiteStatus,
    websiteScore: d.websiteScore,
    confidenceScore,
    techStack: d.techStack,
    digitalPresence: d.digitalPresence,
    evidenceMatrix: d.evidenceMatrix,
    detectedProblems: d.detectedProblems,
    conversionFriction: d.detectedProblems,
    summary: `Technical audit and opportunity analysis completed for ${d.companyName}. Recommended service: ${recommendedServiceName}.`,
    opportunity: {
      opportunityScore,
      confidenceScore,
      recommendedServiceCode,
      recommendedServiceName,
      recommendedChannel,
      primaryPainPoint,
      reasoning,
      potentialImpact,
      reasonToContact,
      suggestedOffer,
      expectedBusinessBenefit,
      claimType,
      estimatedBudgetMin,
      estimatedBudgetMax,
      currency: 'AED',
      pitchAngle,
      evidenceSummary
    }
  }
};
